class Node {
    int data;
    Node ref;
}

public class Main {
    public static void main(String[] args) {
        Node n1 = new Node(); n1.data = 4;
        Node n2 = new Node(); n2.data = 5;
        Node n3 = new Node(); n3.data = 8;
        n1.ref = n2;

        n3.ref = n1.ref;
        n1.ref = n3;

        Node cur = n1;
        while (cur != null) {
            System.out.print(cur.data + " ");
            cur = cur.ref;
        }
    }
}

public class Main {
    static int[] arr = new int[10];

    static void add(int el) {
        arr[el % arr.length] = el;
    }

    static boolean contains(int el) {
        return arr[el % arr.length] == el;
    }

    public static void main(String[] args) {
        add(10);
        add(12);
        add(6);
        add(100);
        System.out.println(contains(10) + " " + contains(100) + " " + contains(12));
    }
}

class DynamicArray {
    int[] arr = new int[2];
    int size = 0;

    void add(int el) {
        if (size == arr.length) {
            int[] bigger = new int[arr.length * 2];
            for (int i = 0; i < size; i++) {
                bigger[i] = arr[i];
            }
            arr = bigger;
        }
        arr[size++] = el;
    }
}

public class Main {
    public static void main(String[] args) {
        DynamicArray da = new DynamicArray();
        int[] values = {4, 10, 13, 15, 17};
        for (int v : values) {
            da.add(v);
        }
        System.out.println(da.arr.length + " " + da.size + " " + da.arr[da.size - 1]);
    }
}
